"""Prepare immutable slots only; does not call a solver."""
import hashlib,json,pathlib,sys,platform
ROOT=pathlib.Path(__file__).resolve().parents[1]
def write(name,value):
    with (ROOT/name).open('w') as f:json.dump(value,f,indent=2);f.write('\n')
def main():
    data=json.loads((ROOT/'data/historical_numeric.json').read_text());slots=[]
    for n in (1000,5000,10000):
        for ins in data['instances']:
            if ins['n']!=n:continue
            for capacity in (100,500):
                for method in ('FF','BF'):
                    slots.append({'index':len(slots),'id':f"{ins['id']}_c{capacity}_{method}",'instance_id':ins['id'],'items_sha256':ins['items_sha256'],'source_dtype':ins['source_dtype'],'source_commit':data['source_commit'],'n':n,'capacity':capacity,'method':method,'phase':'calibration_included' if n==1000 else 'remaining_frozen','status':'not_run_pending_authorization'})
    if len(slots)!=60:raise ValueError('slot count')
    protocol={'identity':'p3_eoh_2024_data_corrected_ff_bf_v1','scope':'Trusted handwritten FF/BF on pinned public test datasets; no author heuristic execution, candidate execution, or EoH evolution','official_data_commit':'e4b5ddba03b2b88025747e11c6049f8b529a4368','official_correction_reference_commit':'472545785c936dcfc863d2bc0d6109cf23c7ce62','data_identity':'Author ICML2024-era repository test files; same blobs through2026 pre-replacement revision. This does not prove exact paper table-run byte provenance.','slot_count':60,'instance_count':15,'capacities':[100,500],'size_order':[1000,5000,10000],'method_order':['FF','BF'],'allocation':'n capacity-filled bins; all feasible indices in original order including unused bins; first maximum score tie','arithmetic':'exact Python integers; equivalent to pinned integer-array FF/BF scoring, no NumPy algorithm timing claim','primary_statistic':'(sum(used_bins)-sum(L1))/sum(L1), five instances per size/capacity/method; L1=ceil(sum(items)/capacity)','stopping':'stop on any integrity, transport, worker failure, invalid assignment, or insufficient full-call budget; preserve all slots and attempts; no retry','budgets':{'batch_accounted_total_cpu_seconds':300,'batch_wall_seconds':600,'worker_cpu_seconds':20,'worker_wall_seconds':30,'cleanup_seconds':1,'worker_address_space_bytes':2147483648,'supervisor_address_space_bytes':2147483648,'supervisor_cpu_seconds':300,'worker_output_bytes':400000,'worker_file_size_bytes':0,'worker_nofile':32,'batch_reservation_worker_cpu_seconds':20,'batch_reservation_wall_seconds':31},'budget_caveats':['Batch CPU accounts wait4 worker user+system plus supervisor process_time; each process also has its own RLIMIT_CPU; aggregate300s is an observed/reservation bound, not kernel process-tree quota','600s whole-stage wall is observed and reserved before each call; each worker has a30s kill deadline plus1s cleanup. Final integrity/statistics/publication are charged; final bounded accounting-snapshot write remains outside the last measurement. Overshoot invalidates completed certification and is reported.','2GiB RLIMIT_AS is per-process virtual address space, not total RSS; one supervisor+one worker at a time','Fresh trusted worker each slot; no untrusted code is accepted; rlimits are resource bounds, not a capability sandbox'],'sample_dependence':['Both methods and both capacities reuse each original sequence','Public reproduction data, not a new heldout test','First20 calibration slots remain in results; no adaptive budget/source change'],'capacity_correction':'Every instance gets requested capacity100 or500 with unchanged absolute item sizes; historical first-instance-only capacity bug is not reproduced as main result','execution_gate':'Requires external approval matching exact freeze digest and one-use run ID; preparation is not batch authorization','runtime':{'python':sys.version,'executable':sys.executable,'platform':platform.platform(),'external_dependencies':[]}}
    write('protocol.json',protocol);write('prepared_plan.json',{'protocol':protocol['identity'],'slots':slots})
if __name__=='__main__':main()
